import torch


def gen_inputs(ctx, device):
    sparse_dim = ctx['sparse_dim']
    dense_dim = ctx['dense_dim']
    size = [int(s) for s in ctx['size']]
    values_shape = tuple(int(v) for v in ctx['values__shape'])
    indices_dtype = getattr(torch, ctx['indices__dtype'])
    values_dtype = getattr(torch, ctx['values__dtype'])
    nnz = values_shape[0]
    sparse_size = size[:sparse_dim]
    total = 1
    for s in sparse_size:
        total *= s
    nse = min(nnz, total)
    if total > 0:
        if nse * 2 >= total:
            chosen = torch.randperm(total, device=device)[:nse].sort().values
        else:
            num = min(total, max(nse * 2, 256))
            chosen = torch.unique(torch.randint(0, total, (num,), device=device))[:nse]
            for _ in range(8):
                if chosen.numel() >= nse:
                    break
                num = min(total, max((nse - chosen.numel()) * 2, 256))
                chosen = torch.unique(torch.cat([
                    chosen,
                    torch.randint(0, total, (num,), device=device),
                ]))[:nse]
            chosen = chosen.sort().values
        idx_cols = []
        for k in range(sparse_dim):
            stride = 1
            for j in range(k + 1, sparse_dim):
                stride *= sparse_size[j]
            idx_cols.append((chosen // stride) % sparse_size[k])
        indices = torch.stack(idx_cols, dim=0).to(indices_dtype)
    else:
        indices = torch.empty((sparse_dim, 0), dtype=indices_dtype, device=device)
    values = torch.randn((nse,) + tuple(values_shape[1:]), dtype=values_dtype, device=device)
    return {'indices': indices, 'values': values}


def run(sparse_dim, dense_dim, size, indices, values):
    size = [int(s) for s in size]
    dense = torch.zeros(size, dtype=values.dtype, device=values.device)
    if indices.shape[1] > 0:
        dense[tuple(indices[i] for i in range(sparse_dim))] = values
    return dense
